CardSpoke_MODS.register('minimal-writer', {
  onLoad: function(ctx) {
    document.body.classList.add('mod-minimal-writer');
    ctx.logger.info('Minimal Writer activated');
  },
  onDisable: function(ctx) {
    document.body.classList.remove('mod-minimal-writer');
    ctx.logger.info('Minimal Writer deactivated');
  },
  onUninstall: function(ctx) {
    document.body.classList.remove('mod-minimal-writer');
  }
});
